    //= parallel-v6-udp-dgram-prohibited-r3: every TTL the router the topology puts there
    //= parallel-v6-udp-flow-prohibited-r3: every TTL the router the topology puts there
    //= parallel-v6-icmp-silent-r2: every TTL the router the topology puts there
    //= parallel-v6-udp-silent-r2: every TTL the router the topology puts there
    //= parallel-v6-tcp-silent-r2: every TTL the router the topology puts there
    //= parallel-v6-icmp-dgram-silent-r2: every TTL the router the topology puts there
    //= parallel-v6-udp-dgram-silent-r2: every TTL the router the topology puts there
    //= parallel-v6-udp-flow-silent-r2: every TTL the router the topology puts there
    //= ecmp: classic UDP probes see both balanced routers at TTL 2, flow-stable ones see one; the kernel computes the UDP checksum the id asks for
};
